      imgDisplace = imgs[0]; imgSpark = imgs[1]; imgNoise = imgs[2]
      NOISE_W = imgDisplace.naturalWidth; NOISE_H = imgDisplace.naturalHeight
      const c = document.createElement('canvas'); c.width = NOISE_W; c.height = NOISE_H
