    S,
    errMsg,
    dragging,
    frameRef,
    stageRef,
    viewRef,
    overlayRef,
    fileRef,
    toolName,
    gl,
    progBlock,
    texDisplace,
    imgDisplace,
    noiseR,
    maskKey,
    dirty,
    cacheBlock,
    rafId,
    showErr,
    createGL,
    compile,
    link,
    texFromImage,
    makeSolid,
    initGL,
    uB,
    uBlit,
    CELL_BIT,
    cellMatches,
    paintCell,
    buildZones,
    dilate32,
    computeMasks,
    uploadMask,
    previewDims,
    MASK_MAX,
    BW_MAX,
    maskDims,
    blockDiv,
    maskGrid,
    maskBlockPx,
    edgePassesOf,
    edgeTexelPx,
    fmtPx,
    blockInfo,
    edgeInfo,
    blockInfoText,
    edgeInfoText,
    bind,
    renderInto,
    _renderT0,
    renderNow,
    requestRender,
    normRect,
    drawOverlay,
    snapshot,
    pushUndo,
    restore,
    undo,
    redo,
    stampCircle,
    bucketFill,
    strokeTo,
    eraseRectsAt,
